{
  "goalId": "262f807a-30d0-503e-986f-856cbd048e8e",
  "reason": "Achsenabschnitte und Steigungen legen Anfangswerte und konstante Beschleunigung fest; t-v-Flächen bestimmen dazu das Ortsgesetz. / Graph intercepts and slopes fix initial values and constant acceleration; t-v areas then determine the position law.",
  "profile": {
    "archetype": "procedure",
    "expectations": [
      {
        "id": "infer-laws-from-graphs",
        "essentialUnderstandingDe": "Für gleichförmige Bewegung gilt v(t) = v0 und s(t) = s0 + v0t; bei konstantem a gilt v(t) = v0 + at und s(t) = s0 + v0t + ½at². t wird ab dem angegebenen Anfangszeitpunkt gemessen.",
        "essentialUnderstandingEn": "For uniform motion, v(t) = v0 and s(t) = s0 + v0t; for constant a, v(t) = v0 + at and s(t) = s0 + v0t + ½at². Time t is measured from the stated initial instant.",
        "observablePerformanceDe": "Wählt anhand neuer Zeitdiagramme das passende der beiden Modelle und ermittelt s0, v0 und gegebenenfalls a aus Achsenabschnitten, Steigungen oder Flächen; formuliert beide Gesetze mit Einheiten und konsistenten Vorzeichen.",
        "observablePerformanceEn": "Selects the appropriate model from fresh time graphs and obtains s0, v0, and, where needed, a from intercepts, slopes, or areas; formulates both laws with units and consistent signs."
      },
      {
        "id": "explain-law-connection",
        "essentialUnderstandingDe": "Die Geschwindigkeit beschreibt die Steigung des Ortsgraphen; die vorzeichenbehaftete t-v-Fläche ergibt s(t) − s0. Bei linear veränderlichem v liefert die Trapezfläche den Faktor ½.",
        "essentialUnderstandingEn": "Velocity describes the position graph's slope; signed t-v area gives s(t) − s0. For linearly changing v, the trapezoid area supplies the factor ½.",
        "observablePerformanceDe": "Begründet den Zusammenhang der selbst bestimmten Gesetze anhand der Diagramme und ihrer physikalischen Bedeutung, etwa über Steigungen, vorzeichenbehaftete Rechteck- oder Trapezflächen oder mittlere Geschwindigkeit mal Zeitspanne, und prüft mindestens einen gemeinsamen Zeitpunkt am Ausgangsdiagramm. Differentialrechnung wird nicht vorausgesetzt, darf aber für eine gleichwertige fachlich richtige Begründung genutzt werden.",
        "observablePerformanceEn": "Explains the connection between the self-determined laws through the graphs and their physical meaning, for example using slopes, signed rectangle or trapezoid areas, or mean velocity times elapsed time, and checks at least one common instant against the source graph. Calculus is not required but may be used for an equivalent physically sound justification."
      },
      {
        "id": "predict-and-check",
        "essentialUnderstandingDe": "Eine Vorhersage für Ort und Geschwindigkeit gilt für das gewählte Modellintervall; Anfangsort, Bewegungsrichtung und Einheiten bleiben dabei erhalten.",
        "essentialUnderstandingEn": "A position and velocity prediction applies within the selected model interval; it retains initial position, direction of motion, and units.",
        "observablePerformanceDe": "Sagt mit den erschlossenen Gesetzen Ort und Geschwindigkeit zu einem neuen Zeitpunkt voraus und prüft Anfangswerte, Vorzeichen und Plausibilität am beschriebenen Bewegungsverlauf.",
        "observablePerformanceEn": "Uses the inferred laws to predict position and velocity at a new instant and checks initial values, signs, and plausibility against the described motion."
      }
    ],
    "coverageExpectations": {
      "requiredExpectationIds": [
        "infer-laws-from-graphs",
        "explain-law-connection",
        "predict-and-check"
      ],
      "alternativeExpectationGroups": [],
      "minimumIndependentDemonstrations": 2,
      "freshVariationRequired": true,
      "independentTransferRequired": true
    },
    "variationAxes": [
      {
        "id": "motion-model",
        "textDe": "Gleichförmige Bewegung gegenüber Bewegung mit konstanter, von null verschiedener Beschleunigung.",
        "textEn": "Uniform motion versus motion with constant nonzero acceleration."
      },
      {
        "id": "graph-and-sign",
        "textDe": "Zeit-Ort-Graph gegenüber Zeit-Geschwindigkeits-Graph; negativer Bewegungsbeginn mit oder ohne späteren Richtungswechsel.",
        "textEn": "Time-position versus time-velocity source graph; initially negative velocity with or without a later reversal."
      }
    ],
    "applicationCaseBriefs": [
      {
        "id": "uniform-negative-velocity",
        "taskDemandDe": "Ein t-s-Graph ist im Modellintervall 0 bis 6 s die Gerade durch (0 s; 5 m), (2 s; 3 m) und (4 s; 1 m). Erschließe beide Zeitgesetze, erläutere ihren Zusammenhang und sage s und v bei 6 s voraus.",
        "taskDemandEn": "Within the model interval 0 to 6 s, a t-s graph is the straight line through (0 s, 5 m), (2 s, 3 m), and (4 s, 1 m). Infer both time laws, explain their connection, and predict s and v at 6 s.",
        "expectedPerformanceDe": "Leitet v0 = −1 m/s und s(t) = 5 m − (1 m/s)t, v(t) = −1 m/s her. Begründet den Zusammenhang etwa über die negative Steigung oder Δs = −6 m als t-v-Rechteckfläche; gleichwertige graphenbezogene physikalische Begründungen sind zulässig. Erhält s(6 s) = −1 m und v(6 s) = −1 m/s.",
        "expectedPerformanceEn": "Derives v0 = −1 m/s and s(t) = 5 m − (1 m/s)t, v(t) = −1 m/s. Explains the connection, for example through the negative slope or Δs = −6 m as a t-v rectangle area; equivalent graph-based physical justifications are acceptable. Obtains s(6 s) = −1 m and v(6 s) = −1 m/s.",
        "understandingFocusDe": "Ein negativer Endort und eine negative Geschwindigkeit haben unterschiedliche Bedeutungen; der Anfangsort geht nur in das Ortsgesetz ein.",
        "understandingFocusEn": "Negative final position and negative velocity have distinct meanings; initial position enters only the position law."
      },
      {
        "id": "accelerated-velocity-source",
        "taskDemandDe": "Ein t-v-Graph ist für 0 bis 5 s eine Gerade durch (0 s; −2 m/s), (2 s; 0) und (4 s; +2 m/s); s(0) = 3 m. Bestimme beide Gesetze, prüfe sie bei 2 s und sage s und v bei 5 s voraus.",
        "taskDemandEn": "For 0 to 5 s, a t-v graph is a straight line through (0 s, −2 m/s), (2 s, 0), and (4 s, +2 m/s); s(0) = 3 m. Determine both laws, check them at 2 s, and predict s and v at 5 s.",
        "expectedPerformanceDe": "Erschließt a = +1 m/s², v(t) = −2 m/s + (1 m/s²)t und s(t) = 3 m − (2 m/s)t + (0,5 m/s²)t². Prüft bei 2 s: v = 0 und s = 1 m, etwa über die negative Dreiecksfläche oder mittlere Geschwindigkeit mal Zeitspanne; gleichwertige graphenbezogene physikalische Begründungen sind zulässig. Erhält bei 5 s s = 5,5 m und v = +3 m/s.",
        "expectedPerformanceEn": "Infers a = +1 m/s², v(t) = −2 m/s + (1 m/s²)t and s(t) = 3 m − (2 m/s)t + (0.5 m/s²)t². Checks at 2 s: v = 0 and s = 1 m, for example using the negative triangle area or mean velocity times elapsed time; equivalent graph-based physical justifications are acceptable. Obtains s = 5.5 m and v = +3 m/s at 5 s.",
        "understandingFocusDe": "Anfangsgeschwindigkeit und konstante Beschleunigung bestimmen gemeinsam das Ortsgesetz; vorzeichenbehaftete Flächen erhalten den Zusammenhang auch bei Richtungswechsel.",
        "understandingFocusEn": "Initial velocity and constant acceleration jointly determine the position law; signed areas preserve the connection through a reversal."
      }
    ]
  }
}
{
  "goalId": "09029573-864f-40ca-bf8a-cee7bf6dcb73",
  "reason": "Die quadratische Zeitabhängigkeit des Orts erlaubt im widerstandsfreien Modell die grafische Bestimmung von g; Anfangswerte und Achsenrichtung bestimmen das vollständige Ortsgesetz. / Quadratic position dependence on time enables graphical determination of g in the drag-free model; initial values and axis direction determine the complete position law.",
  "profile": {
    "archetype": "experiment",
    "expectations": [
      {
        "id": "collect-free-fall-data",
        "essentialUnderstandingDe": "Beim freien Fall nahe der Erdoberfläche gilt näherungsweise konstante Beschleunigung, wenn Luftwiderstand vernachlässigbar ist. Gemessene Orte und Zeiten sind von daraus erschlossenem g zu unterscheiden.",
        "essentialUnderstandingEn": "Free fall near Earth's surface has approximately constant acceleration when air resistance is negligible. Measured positions and times must be distinguished from the inferred g.",
        "observablePerformanceDe": "Formuliert eine prüfbare Frage zur Zeit-Ort-Beziehung und erhebt selbst mehrere Messpunkte mit Wiederholungen. Begründet Messprinzip, kontrollierte Freigabe und Kalibrierung; dokumentiert Rohdaten, eigene Beiträge sowie Zeit- und Ortsunsicherheiten. Nutzt geringe Fallhöhe, freien Fallbereich und Auffangbehälter. Für die frische unabhängige Transferdemonstration ist auch eine gesondert bereitgestellte, klar zugeordnete Aufnahme oder Messreihe zulässig; deren Herkunft und eigene Auswertung werden getrennt dokumentiert.",
        "observablePerformanceEn": "Formulates a testable question about the time-position relationship and personally collects several measurements with repeats. Justifies the measurement principle, controlled release and calibration; documents raw data, personal contributions and time and position uncertainties. Uses a low drop height, clear falling area and catch container. The fresh independent transfer demonstration may also use a separately supplied, clearly attributed recording or measurement series; its provenance and the learner's analysis are documented separately."
      },
      {
        "id": "graphical-g-inference",
        "essentialUnderstandingDe": "Bei Start aus Ruhe gilt für die Fallstrecke h = g·t²/2; allgemeiner entspricht der quadratische Koeffizient im Zeit-Ort-Graphen der halben vorzeichenbehafteten Beschleunigung.",
        "essentialUnderstandingEn": "For release from rest, falling distance obeys h = g·t²/2; more generally the quadratic coefficient in the position-time graph equals half the signed acceleration.",
        "observablePerformanceDe": "Wählt eine zu den Anfangsbedingungen der ausgewerteten Messreihe passende grafische Auswertung, bestimmt g etwa aus einer begründeten Steigung oder quadratischen Anpassung mit Einheit und gibt eine durch Auflösung und Streuung gestützte Unsicherheit an. Prüft Modellabweichungen, ohne Messwerte auf einen Sollwert zu zwingen.",
        "observablePerformanceEn": "Selects graphical analysis suited to the initial conditions of the analyzed series, determines g, for example from a justified slope or quadratic fit, with units and states uncertainty supported by resolution and scatter. Checks model departures without forcing measurements to a target value."
      },
      {
        "id": "initial-conditions-law",
        "essentialUnderstandingDe": "Für konstante Beschleunigung gilt s(t) = s0 + v0·t + a·t²/2. Der Betrag g ist positiv; das Vorzeichen von a hängt von der Achsenrichtung ab. v0 = 0 gilt nur bei geeigneter Freigabe und Zeitwahl.",
        "essentialUnderstandingEn": "For constant acceleration, s(t) = s0 + v0·t + a·t²/2. The magnitude g is positive; the sign of a depends on axis direction. v0 = 0 applies only with suitable release and choice of time origin.",
        "observablePerformanceDe": "Formuliert für jede ausgewertete Messreihe das vollständige Gesetz mit gemessenem oder begründetem s0, v0 und erschlossenem a. Benennt Nullzeit und Achsenrichtung und vergleicht eine vorhergesagte Position mit der Messung unter Berücksichtigung der Unsicherheit.",
        "observablePerformanceEn": "Formulates the complete law for each analyzed series using measured or justified s0 and v0 and inferred a. States the time origin and axis direction and compares a predicted position with measurement while accounting for uncertainty."
      }
    ],
    "coverageExpectations": {
      "requiredExpectationIds": [
        "collect-free-fall-data",
        "graphical-g-inference",
        "initial-conditions-law"
      ],
      "alternativeExpectationGroups": [],
      "minimumIndependentDemonstrations": 2,
      "freshVariationRequired": true,
      "independentTransferRequired": true
    },
    "variationAxes": [
      {
        "id": "measurement-principle",
        "textDe": "Fallzeitmessung für mehrere Freigabehöhen gegenüber kalibrierter Bildmessung einer neuen eigenen oder gesondert bereitgestellten, klar zugeordneten Fallreihe.",
        "textEn": "Fall-time measurement for several release heights versus calibrated image measurement of a new personal or separately supplied, clearly attributed drop series."
      },
      {
        "id": "initial-time-and-sign",
        "textDe": "Abwärts positive Fallstrecke ab Freigabe gegenüber verändertem Ortsnullpunkt und aufwärts positiver Achse bei Freigabe aus Ruhe oder, als weitere Möglichkeit, bei Nullzeit während des Falls mit v0 ungleich null.",
        "textEn": "Downward-positive falling distance from release versus a changed position origin and upward-positive axis at release from rest or, as a further option, a time origin during the fall with nonzero v0."
      }
    ],
    "applicationCaseBriefs": [
      {
        "id": "release-height-series",
        "taskDemandDe": "Untersuche selbst den Fall einer kompakten Kugel aus Ruhe aus mehreren niedrigen Höhen, etwa 0,20–0,65 m. Wähle eine hinreichend genaue Fallzeitmessung, wiederhole die Messungen und bestimme g grafisch mit abwärts positiver Fallstrecke.",
        "taskDemandEn": "Personally investigate a compact ball released from rest at several low heights, for example 0.20–0.65 m. Choose sufficiently accurate fall-time measurement, repeat measurements and determine g graphically using downward-positive falling distance.",
        "expectedPerformanceDe": "Liefert eigene Höhen und Zeiten mit Unsicherheiten, einen h-gegen-t²-Graphen und g als doppelte Steigung. Modellreferenz, keine Soll-Rohdaten: Bei g = 9,81 m/s² ergeben 0,20 und 0,50 m etwa 0,202 und 0,319 s. Formuliert h(t) = gMess·t²/2 mit h0 = 0 und v0 = 0 und prüft die Messverträglichkeit.",
        "expectedPerformanceEn": "Provides personal heights and times with uncertainties, an h-versus-t² graph and g as twice the slope. Model reference, not target raw data: with g = 9.81 m/s², 0.20 and 0.50 m correspond to about 0.202 and 0.319 s. Formulates h(t) = gMeasured·t²/2 with h0 = 0 and v0 = 0 and checks agreement with measurement.",
        "understandingFocusDe": "Die grafische Steigung erschließt g aus eigenen Messungen; Freigabe und Nullzeit rechtfertigen den fehlenden linearen Term.",
        "understandingFocusEn": "The graph's slope infers g from personal measurements; release and time origin justify the absent linear term."
      },
      {
        "id": "in-flight-time-origin",
        "taskDemandDe": "Nutze für eine unabhängige neue grafische Auswertung eine eigene sichere Fallaufnahme mit Wiederholungen, kalibriertem Maßstab und bekannter Bildzeit oder eine gesondert bereitgestellte, klar zugeordnete Aufnahme/Messreihe mit dokumentierter Kalibrierung und Zeitbasis. Wähle aufwärts als positive Richtung und t = 0 erst während des Falls; alternativ ändere Ortsnullpunkt und Achsenrichtung bei Freigabe aus Ruhe. Bestimme grafisch g und ein Gesetz mit passenden Anfangswerten.",
        "taskDemandEn": "For a fresh independent graphical analysis, use a personal safe drop recording with repeats, a calibrated scale and known frame timing, or a separately supplied, clearly attributed recording/measurement series with documented calibration and time base. Choose upward positive and t = 0 during the fall; alternatively change the position origin and axis direction at release from rest. Determine g graphically and obtain a law with appropriate initial values.",
        "expectedPerformanceDe": "Kennzeichnet eigene oder fremde Messdaten samt Herkunft und zeigt eine eigenständige grafische Bestimmung von g passend zu den Anfangsbedingungen. Eine grafische quadratische Anpassung mit negativem quadratischem Koeffizienten und v0 < 0 bei aufwärts positiver Achse und Nullzeit während des Falls ist eine Möglichkeit; bei Freigabe aus Ruhe sind andere passende grafische Bestimmungen zulässig. Optionale Modellreferenz: Freigabe aus Ruhe bei y = 0,80 m, aufwärts positiv, Nullzeit bei y0 = 0,60 m und g = 9,8 m/s² ergibt v0 ≈ −1,98 m/s sowie y(0,10 s) ≈ 0,353 m. Berichtet die selbst erschlossenen Werte mit ihren Unsicherheiten und prüft das Gesetz am eigenständig erstellten Graphen; maßgeblich ist die Messverträglichkeit, nicht die Übereinstimmung mit den Referenzwerten.",
        "expectedPerformanceEn": "Identifies personal or supplied measurements and their provenance and independently determines g graphically in a way suited to the initial conditions. A graphical quadratic fit with a negative quadratic coefficient and v0 < 0 for upward positive and an in-flight time origin is one option; other appropriate graphical determinations are acceptable for release from rest. Optional model reference: release from rest at y = 0.80 m, upward positive, time origin at y0 = 0.60 m and g = 9.8 m/s² give v0 ≈ −1.98 m/s and y(0.10 s) ≈ 0.353 m. Reports independently inferred values with their uncertainties and checks the law against the independently constructed graph; agreement with the measurements within uncertainty, rather than with the reference values, is decisive.",
        "understandingFocusDe": "Koordinaten und Nullzeit ändern Koeffizienten und Anfangswerte, aber nicht den erschlossenen Betrag der Fallbeschleunigung.",
        "understandingFocusEn": "Coordinates and time origin change coefficients and initial values but not the inferred magnitude of gravitational acceleration."
      }
    ]
  }
}
{
  "goalId": "89a8cf15-7ba4-46c1-b1dc-fd161b20d9c2",
  "reason": "Dieselbe Zeit verbindet die unabhängigen horizontalen und vertikalen Bewegungen; ihre gemeinsame Ortsdarstellung ergibt die parabelförmige Flugbahn. / The same time connects independent horizontal and vertical motions; their joint position representation yields the parabolic trajectory.",
  "profile": {
    "archetype": "experiment",
    "expectations": [
      {
        "id": "record-horizontal-launch",
        "essentialUnderstandingDe": "Ein waagerechter Start bedeutet vy0 = 0; beide Ortskomponenten müssen zu denselben Zeitpunkten erfasst werden. Eine geneigte Freigabe oder perspektivisch verzerrte Aufnahme kann die Deutung verfälschen.",
        "essentialUnderstandingEn": "A horizontal launch means vy0 = 0; both position components must be recorded at the same times. An inclined release or perspective-distorted recording can bias interpretation.",
        "observablePerformanceDe": "Plant und führt selbst einen niedrigen waagerechten Wurf zur Untersuchung der Teilbewegungen aus. Kontrolliert Startausrichtung und Höhe, kalibriert Orts- und Zeitmessung und erhebt eigene zeitgleiche x-y-Daten. Dokumentiert Rohdaten, eigene Beiträge und Unsicherheiten; sichert Flugbereich und Auffangen.",
        "observablePerformanceEn": "Plans and personally performs a low horizontal launch to investigate component motions. Controls launch alignment and height, calibrates position and time measurement and collects personal simultaneous x-y data. Documents raw data, personal contributions and uncertainties; secures the flight area and catch."
      },
      {
        "id": "test-component-superposition",
        "essentialUnderstandingDe": "Bei vernachlässigbarem Luftwiderstand und konstantem g bleibt die horizontale Geschwindigkeit konstant; die vertikale Bewegung ist bei vy0 = 0 gleichmäßig beschleunigt. Die Komponenten teilen die Zeit und beeinflussen einander in diesem Modell nicht.",
        "essentialUnderstandingEn": "With negligible air resistance and constant g, horizontal velocity remains constant; vertical motion with vy0 = 0 is uniformly accelerated. The components share time and do not influence one another in this model.",
        "observablePerformanceDe": "Prüft eigene Daten auf gleiche horizontale und wachsende vertikale Ortsänderungen in gleichen Zeitspannen. Vergleicht eine begründete Modellvorhersage mit Messpunkten und benennt unter Berücksichtigung der Unsicherheit mögliche Start-, Perspektiv- oder Luftwiderstandseinflüsse.",
        "observablePerformanceEn": "Checks personal data for equal horizontal and growing vertical position changes over equal time spans. Compares a justified model prediction with measurements and identifies possible launch, perspective or air-resistance effects while accounting for uncertainty."
      },
      {
        "id": "construct-trajectory",
        "essentialUnderstandingDe": "Das x-y-Diagramm verknüpft zeitgleiche Ortskomponenten und zeigt unter diesen Bedingungen eine Parabel. Es stellt eine räumliche Flugbahn dar.",
        "essentialUnderstandingEn": "The x-y graph combines simultaneous position components and shows a parabola under these conditions. It represents a spatial trajectory.",
        "observablePerformanceDe": "Konstruiert aus eigenen Messpunkten ein skaliertes x-y-Diagramm mit Ursprung, Achsenrichtungen und Einheiten. Erklärt die Krümmung durch gleichförmige horizontale und beschleunigte vertikale Bewegung; unterscheidet Messpunkte, Modellkurve und Zeit-Ort-Diagramm.",
        "observablePerformanceEn": "Constructs a scaled x-y graph from personal measurements with origin, axis directions and units. Explains curvature through uniform horizontal and accelerated vertical motion; distinguishes measured points, model curve and position-time graph."
      }
    ],
    "coverageExpectations": {
      "requiredExpectationIds": [
        "record-horizontal-launch",
        "test-component-superposition",
        "construct-trajectory"
      ],
      "alternativeExpectationGroups": [],
      "minimumIndependentDemonstrations": 2,
      "freshVariationRequired": true,
      "independentTransferRequired": true
    },
    "variationAxes": [
      {
        "id": "launch-direction-and-speed",
        "textDe": "Start nach rechts gegenüber einem neuen Start nach links mit anderer Geschwindigkeit bei gleicher Höhe.",
        "textEn": "Launch to the right versus a new launch to the left at a different speed from the same height."
      },
      {
        "id": "vertical-coordinate",
        "textDe": "Abwärts positive Achse ab Startpunkt gegenüber aufwärts positiver Achse ab Auffanghöhe.",
        "textEn": "Downward-positive axis from the launch point versus upward-positive axis from the catch height."
      }
    ],
    "applicationCaseBriefs": [
      {
        "id": "rightward-own-launch",
        "taskDemandDe": "Untersuche selbst einen langsamen waagerechten Kugelstart nach rechts aus etwa 0,45 m Höhe über einem Auffangbehälter. Gewinne eigene zeitgleiche x-y-Messungen, wähle den Startpunkt als Ursprung und y abwärts positiv und prüfe die Überlagerung anhand der Daten.",
        "taskDemandEn": "Personally investigate a slow horizontal ball launch to the right from about 0.45 m above a catch container. Obtain personal simultaneous x-y measurements, choose the launch point as origin and y downward positive and test superposition using the data.",
        "expectedPerformanceDe": "Legt eigene Rohdaten, Auflösungen und eine x-y-Flugbahn vor; vergleicht horizontale und vertikale Änderungen in gleichen Zeitspannen. Modellreferenz bei vx = 1,0 m/s und g = 9,8 m/s²: (x,y) = (0,100; 0,049) m bei 0,10 s und (0,200; 0,196) m bei 0,20 s. Bewertet eigene Abweichungen anhand der Unsicherheit.",
        "expectedPerformanceEn": "Provides personal raw data, resolutions and an x-y trajectory; compares horizontal and vertical changes over equal time spans. Model reference with vx = 1.0 m/s and g = 9.8 m/s²: (x,y) = (0.100, 0.049) m at 0.10 s and (0.200, 0.196) m at 0.20 s. Evaluates personal deviations using uncertainty.",
        "understandingFocusDe": "Gleiche horizontale Schritte bei zunehmendem vertikalem Fall erzeugen gemeinsam die gekrümmte räumliche Bahn.",
        "understandingFocusEn": "Equal horizontal steps together with increasing vertical fall generate the curved spatial trajectory."
      },
      {
        "id": "leftward-own-launch",
        "taskDemandDe": "Führe selbst eine neue Messreihe mit waagerechtem Start nach links und anderer Startgeschwindigkeit aus gleicher Höhe durch. Wähle x nach rechts, x = 0 am Start und y ab Auffanghöhe nach oben positiv. Konstruiere die Flugbahn und prüfe den Einfluss der horizontalen Änderung auf den vertikalen Verlauf.",
        "taskDemandEn": "Personally perform a new measurement series with horizontal launch to the left at a different speed from the same height. Choose x positive rightward, x = 0 at launch and y positive upward from the catch height. Construct the trajectory and test the effect of the horizontal change on vertical evolution.",
        "expectedPerformanceDe": "Erhebt neue eigene Daten und zeigt abnehmendes x sowie fallendes y mit wachsenden vertikalen Ortsänderungsbeträgen. Modellreferenz bei y0 = 0,45 m, vx = −1,5 m/s und g = 9,8 m/s²: (x,y) = (−0,150; 0,401) m bei 0,10 s und (−0,300; 0,254) m bei 0,20 s. Vergleicht die Fallstrecken beider Reihen zu gleichen Zeiten mit Unsicherheiten.",
        "expectedPerformanceEn": "Collects new personal data and shows decreasing x and falling y with growing magnitudes of vertical position changes. Model reference with y0 = 0.45 m, vx = −1.5 m/s and g = 9.8 m/s²: (x,y) = (−0.150, 0.401) m at 0.10 s and (−0.300, 0.254) m at 0.20 s. Compares falling distances in both series at equal times with uncertainties.",
        "understandingFocusDe": "Horizontale Startrichtung und Geschwindigkeit ändern die räumliche Bahn, im Modell aber nicht die vertikale Bewegung bei gleichen vertikalen Anfangsbedingungen.",
        "understandingFocusEn": "Horizontal launch direction and speed change the spatial trajectory but, in the model, do not change vertical motion with matching vertical initial conditions."
      }
    ]
  },
  "evidenceLevel": "E1",
  "maximumClaimScope": "G1",
  "dissent": []
}

item.text:
{
  "goals": [
    {
      "goalId": "262f807a-30d0-503e-986f-856cbd048e8e",
      "reason": "Graphen und Anfangsdaten bestimmen die Zeitgesetze; Vorzeichen werden relativ zur festen Achsenkonvention gedeutet. / Graphs and initial data determine the time laws; signs are interpreted relative to the fixed axis convention.",
      "profile": {
        "archetype": "procedure",
        "expectations": [
          {
            "id": "infer-laws-from-graphs",
            "essentialUnderstandingDe": "Für gleichförmige Bewegung gilt v(t) = v0 und s(t) = s0 + v0t; bei konstantem a gilt v(t) = v0 + at und s(t) = s0 + v0t + ½at². t wird ab dem angegebenen Anfangszeitpunkt gemessen.",
            "essentialUnderstandingEn": "For uniform motion, v(t) = v0 and s(t) = s0 + v0t; for constant a, v(t) = v0 + at and s(t) = s0 + v0t + ½at². Time t is measured from the stated initial instant.",
            "observablePerformanceDe": "Wählt anhand neuer Zeitdiagramme das passende der beiden Modelle und ermittelt s0, v0 und gegebenenfalls a, soweit aus dem gegebenen Graphen bestimmbar, aus Achsenabschnitten, Steigungen oder Flächen; ergänzt separat gegebene Anfangsdaten. Bei einem t-v-Graphen liefern die Flächen nur Ortsänderungen; zur Rekonstruktion von s(t) ist zusätzlich ein separat bekannter Anfangsort s0 erforderlich. Formuliert beide Gesetze mit Einheiten und konsistenten Vorzeichen.",
            "observablePerformanceEn": "Selects the appropriate model from fresh time graphs and obtains s0, v0, and, where needed, a from intercepts, slopes, or areas where determinable from the given graph; supplements these with separately supplied initial data. For a t-v graph, areas give only changes in position; reconstructing s(t) additionally requires a separately known initial position s0. Formulates both laws with units and consistent signs."
          },
          {
            "id": "explain-law-connection",
            "essentialUnderstandingDe": "Die Geschwindigkeit beschreibt die Steigung des Ortsgraphen; die vorzeichenbehaftete t-v-Fläche ergibt s(t) − s0. Bei linear veränderlichem v liefert die Trapezfläche den Faktor ½.",
            "essentialUnderstandingEn": "Velocity describes the position graph's slope; signed t-v area gives s(t) − s0. For linearly changing v, the trapezoid area supplies the factor ½.",
            "observablePerformanceDe": "Begründet den Zusammenhang der selbst bestimmten Gesetze anhand der Diagramme und ihrer physikalischen Bedeutung, etwa über Steigungen, vorzeichenbehaftete Rechteck- oder Trapezflächen oder mittlere Geschwindigkeit mal Zeitspanne, und prüft mindestens einen gemeinsamen Zeitpunkt am Ausgangsdiagramm. Differentialrechnung wird nicht vorausgesetzt, darf aber für eine gleichwertige fachlich richtige Begründung genutzt werden.",
            "observablePerformanceEn": "Explains the connection between the self-determined laws through the graphs and their physical meaning, for example using slopes, signed rectangle or trapezoid areas, or mean velocity times elapsed time, and checks at least one common instant against the source graph. Calculus is not required but may be used for an equivalent physically sound justification."
          },
          {
            "id": "predict-and-check",
            "essentialUnderstandingDe": "Eine Vorhersage für Ort und Geschwindigkeit gilt für das gewählte Modellintervall; sie verwendet den Anfangsort und behält die gewählte Achsenkonvention sowie konsistente Einheiten bei. Das Vorzeichen von v(t) ungleich null gibt die momentane Bewegungsrichtung an; ein Vorzeichenwechsel zeigt einen Richtungswechsel an.",
            "essentialUnderstandingEn": "A position and velocity prediction applies within the selected model interval; it uses the initial position and maintains the chosen axis convention and consistent units. The sign of nonzero v(t) gives the direction of motion at that instant; a sign change indicates reversal.",
            "observablePerformanceDe": "Sagt mit den erschlossenen Gesetzen Ort und Geschwindigkeit zu einem neuen Zeitpunkt voraus und prüft Anfangswerte, Vorzeichen und Plausibilität am beschriebenen Bewegungsverlauf.",
            "observablePerformanceEn": "Uses the inferred laws to predict position and velocity at a new instant and checks initial values, signs, and plausibility against the described motion."
          }
        ],
        "coverageExpectations": {
          "requiredExpectationIds": [
            "infer-laws-from-graphs",
            "explain-law-connection",
            "predict-and-check"
          ],
          "alternativeExpectationGroups": [],
          "minimumIndependentDemonstrations": 2,
          "freshVariationRequired": true,
          "independentTransferRequired": true
        },
        "variationAxes": [
          {
            "id": "motion-model",
            "textDe": "Gleichförmige Bewegung gegenüber Bewegung mit konstanter, von null verschiedener Beschleunigung.",
            "textEn": "Uniform motion versus motion with constant nonzero acceleration."
          },
          {
            "id": "graph-and-sign",
            "textDe": "Zeit-Ort-Graph gegenüber Zeit-Geschwindigkeits-Graph; negativer Bewegungsbeginn mit oder ohne späteren Richtungswechsel.",
            "textEn": "Time-position versus time-velocity source graph; initially negative velocity with or without a later reversal."
          }
        ],
        "applicationCaseBriefs": [
          {
            "id": "uniform-negative-velocity",
            "taskDemandDe": "Ein t-s-Graph ist im Modellintervall 0 bis 6 s die Gerade durch (0 s; 5 m), (2 s; 3 m) und (4 s; 1 m). Erschließe beide Zeitgesetze, erläutere ihren Zusammenhang und sage s und v bei 6 s voraus.",
            "taskDemandEn": "Within the model interval 0 to 6 s, a t-s graph is the straight line through (0 s, 5 m), (2 s, 3 m), and (4 s, 1 m). Infer both time laws, explain their connection, and predict s and v at 6 s.",
            "expectedPerformanceDe": "Leitet v0 = −1 m/s und s(t) = 5 m − (1 m/s)t, v(t) = −1 m/s her. Begründet den Zusammenhang etwa über die negative Steigung oder Δs = −6 m als t-v-Rechteckfläche; gleichwertige graphenbezogene physikalische Begründungen sind zulässig. Erhält s(6 s) = −1 m und v(6 s) = −1 m/s.",
            "expectedPerformanceEn": "Derives v0 = −1 m/s and s(t) = 5 m − (1 m/s)t, v(t) = −1 m/s. Explains the connection, for example through the negative slope or Δs = −6 m as a t-v rectangle area; equivalent graph-based physical justifications are acceptable. Obtains s(6 s) = −1 m and v(6 s) = −1 m/s.",
            "understandingFocusDe": "Ein negativer Endort und eine negative Geschwindigkeit haben unterschiedliche Bedeutungen; der Anfangsort geht nur in das Ortsgesetz ein.",
            "understandingFocusEn": "Negative final position and negative velocity have distinct meanings; initial position enters only the position law."
          },
          {
            "id": "accelerated-velocity-source",
            "taskDemandDe": "Ein t-v-Graph ist für 0 bis 5 s eine Gerade durch (0 s; −2 m/s), (2 s; 0) und (4 s; +2 m/s); s(0) = 3 m. Bestimme beide Gesetze, prüfe sie bei 2 s und sage s und v bei 5 s voraus.",
            "taskDemandEn": "For 0 to 5 s, a t-v graph is a straight line through (0 s, −2 m/s), (2 s, 0), and (4 s, +2 m/s); s(0) = 3 m. Determine both laws, check them at 2 s, and predict s and v at 5 s.",
            "expectedPerformanceDe": "Erschließt a = +1 m/s², v(t) = −2 m/s + (1 m/s²)t und s(t) = 3 m − (2 m/s)t + (0,5 m/s²)t². Prüft bei 2 s: v = 0 und s = 1 m, etwa über die negative Dreiecksfläche oder mittlere Geschwindigkeit mal Zeitspanne; gleichwertige graphenbezogene physikalische Begründungen sind zulässig. Erhält bei 5 s s = 5,5 m und v = +3 m/s.",
            "expectedPerformanceEn": "Infers a = +1 m/s², v(t) = −2 m/s + (1 m/s²)t and s(t) = 3 m − (2 m/s)t + (0.5 m/s²)t². Checks at 2 s: v = 0 and s = 1 m, for example using the negative triangle area or mean velocity times elapsed time; equivalent graph-based physical justifications are acceptable. Obtains s = 5.5 m and v = +3 m/s at 5 s.",
            "understandingFocusDe": "Anfangsgeschwindigkeit und konstante Beschleunigung bestimmen gemeinsam das Ortsgesetz; vorzeichenbehaftete Flächen erhalten den Zusammenhang auch bei Richtungswechsel.",
            "understandingFocusEn": "Initial velocity and constant acceleration jointly determine the position law; signed areas preserve the connection through a reversal."
          }
        ]
      }
    },
    {
      "goalId": "09029573-864f-40ca-bf8a-cee7bf6dcb73",
      "reason": "Die quadratische Zeitabhängigkeit des Orts erlaubt im widerstandsfreien Modell die grafische Bestimmung von g; Anfangswerte und Achsenrichtung bestimmen das vollständige Ortsgesetz. / Quadratic position dependence on time enables graphical determination of g in the drag-free model; initial values and axis direction determine the complete position law.",
      "profile": {
        "archetype": "experiment",
        "expectations": [
          {
            "id": "collect-free-fall-data",
            "essentialUnderstandingDe": "Beim freien Fall nahe der Erdoberfläche gilt näherungsweise konstante Beschleunigung, wenn Luftwiderstand vernachlässigbar ist. Gemessene Orte und Zeiten sind von daraus erschlossenem g zu unterscheiden.",
            "essentialUnderstandingEn": "Free fall near Earth's surface has approximately constant acceleration when air resistance is negligible. Measured positions and times must be distinguished from the inferred g.",
            "observablePerformanceDe": "Formuliert eine prüfbare Frage zur Zeit-Ort-Beziehung und erhebt selbst mehrere Messpunkte mit Wiederholungen. Begründet Messprinzip, kontrollierte Freigabe und Kalibrierung; dokumentiert Rohdaten, eigene Beiträge sowie Zeit- und Ortsunsicherheiten. Nutzt geringe Fallhöhe, freien Fallbereich und Auffangbehälter. Für die frische unabhängige Transferdemonstration ist auch eine gesondert bereitgestellte, klar zugeordnete Aufnahme oder Messreihe zulässig; deren Herkunft und eigene Auswertung werden getrennt dokumentiert.",
            "observablePerformanceEn": "Formulates a testable question about the time-position relationship and personally collects several measurements with repeats. Justifies the measurement principle, controlled release and calibration; documents raw data, personal contributions and time and position uncertainties. Uses a low drop height, clear falling area and catch container. The fresh independent transfer demonstration may also use a separately supplied, clearly attributed recording or measurement series; its provenance and the learner's analysis are documented separately."
          },
          {
            "id": "graphical-g-inference",
            "essentialUnderstandingDe": "Bei Start aus Ruhe gilt für die Fallstrecke h = g·t²/2; allgemeiner entspricht der quadratische Koeffizient im Zeit-Ort-Graphen der halben vorzeichenbehafteten Beschleunigung.",
            "essentialUnderstandingEn": "For release from rest, falling distance obeys h = g·t²/2; more generally the quadratic coefficient in the position-time graph equals half the signed acceleration.",
            "observablePerformanceDe": "Wählt eine zu den Anfangsbedingungen der ausgewerteten Messreihe passende grafische Auswertung, bestimmt g etwa aus einer begründeten Steigung oder quadratischen Anpassung mit Einheit und gibt eine durch Auflösung und Streuung gestützte Unsicherheit an. Prüft Modellabweichungen, ohne Messwerte auf einen Sollwert zu zwingen.",
            "observablePerformanceEn": "Selects graphical analysis suited to the initial conditions of the analyzed series, determines g, for example from a justified slope or quadratic fit, with units and states uncertainty supported by resolution and scatter. Checks model departures without forcing measurements to a target value."
          },
          {
            "id": "initial-conditions-law",
            "essentialUnderstandingDe": "Für konstante Beschleunigung gilt s(t) = s0 + v0·t + a·t²/2. Der Betrag g ist positiv; das Vorzeichen von a hängt von der Achsenrichtung ab. v0 = 0 gilt nur bei geeigneter Freigabe und Zeitwahl.",
            "essentialUnderstandingEn": "For constant acceleration, s(t) = s0 + v0·t + a·t²/2. The magnitude g is positive; the sign of a depends on axis direction. v0 = 0 applies only with suitable release and choice of time origin.",
            "observablePerformanceDe": "Formuliert für jede ausgewertete Messreihe das vollständige Gesetz mit gemessenem oder begründetem s0, v0 und erschlossenem a. Benennt Nullzeit und Achsenrichtung und vergleicht eine vorhergesagte Position mit der Messung unter Berücksichtigung der Unsicherheit.",
            "observablePerformanceEn": "Formulates the complete law for each analyzed series using measured or justified s0 and v0 and inferred a. States the time origin and axis direction and compares a predicted position with measurement while accounting for uncertainty."
          }
        ],
        "coverageExpectations": {
          "requiredExpectationIds": [
            "collect-free-fall-data",
            "graphical-g-inference",
            "initial-conditions-law"
          ],
          "alternativeExpectationGroups": [],
          "minimumIndependentDemonstrations": 2,
          "freshVariationRequired": true,
          "independentTransferRequired": true
        },
        "variationAxes": [
          {
            "id": "measurement-principle",
            "textDe": "Fallzeitmessung für mehrere Freigabehöhen gegenüber kalibrierter Bildmessung einer neuen eigenen oder gesondert bereitgestellten, klar zugeordneten Fallreihe.",
            "textEn": "Fall-time measurement for several release heights versus calibrated image measurement of a new personal or separately supplied, clearly attributed drop series."
          },
          {
            "id": "initial-time-and-sign",
            "textDe": "Abwärts positive Fallstrecke ab Freigabe gegenüber verändertem Ortsnullpunkt und aufwärts positiver Achse bei Freigabe aus Ruhe oder, als weitere Möglichkeit, bei Nullzeit während des Falls mit v0 ungleich null.",
            "textEn": "Downward-positive falling distance from release versus a changed position origin and upward-positive axis at release from rest or, as a further option, a time origin during the fall with nonzero v0."
          }
        ],
        "applicationCaseBriefs": [
          {
            "id": "release-height-series",
            "taskDemandDe": "Untersuche selbst den Fall einer kompakten Kugel aus Ruhe aus mehreren niedrigen Höhen, etwa 0,20–0,65 m. Wähle eine hinreichend genaue Fallzeitmessung, wiederhole die Messungen und bestimme g grafisch mit abwärts positiver Fallstrecke.",
            "taskDemandEn": "Personally investigate a compact ball released from rest at several low heights, for example 0.20–0.65 m. Choose sufficiently accurate fall-time measurement, repeat measurements and determine g graphically using downward-positive falling distance.",
            "expectedPerformanceDe": "Liefert eigene Höhen und Zeiten mit Unsicherheiten und bestimmt g etwa aus einem h-gegen-t²-Graphen als doppelte Steigung; gleichwertige, begründete grafische Bestimmungen mit Einheiten und Unsicherheit sind zulässig. Modellreferenz, keine Soll-Rohdaten: Bei g = 9,81 m/s² ergeben 0,20 und 0,50 m etwa 0,202 und 0,319 s. Formuliert h(t) = gMess·t²/2 mit h0 = 0 und v0 = 0 und prüft die Messverträglichkeit.",
            "expectedPerformanceEn": "Provides personal heights and times with uncertainties and determines g, for example from an h-versus-t² graph as twice the slope; equivalent, justified graphical determinations with units and uncertainty are acceptable. Model reference, not target raw data: with g = 9.81 m/s², 0.20 and 0.50 m correspond to about 0.202 and 0.319 s. Formulates h(t) = gMeasured·t²/2 with h0 = 0 and v0 = 0 and checks agreement with measurement.",
            "understandingFocusDe": "Die grafische Steigung erschließt g aus eigenen Messungen; Freigabe und Nullzeit rechtfertigen den fehlenden linearen Term.",
            "understandingFocusEn": "The graph's slope infers g from personal measurements; release and time origin justify the absent linear term."
          },
          {
            "id": "in-flight-time-origin",
            "taskDemandDe": "Nutze für eine unabhängige neue grafische Auswertung eine eigene sichere Fallaufnahme mit Wiederholungen, kalibriertem Maßstab und bekannter Bildzeit oder eine gesondert bereitgestellte, klar zugeordnete Aufnahme/Messreihe mit dokumentierter Kalibrierung und Zeitbasis. Wähle aufwärts als positive Richtung und t = 0 erst während des Falls; alternativ ändere Ortsnullpunkt und Achsenrichtung bei Freigabe aus Ruhe. Bestimme grafisch g und ein Gesetz mit passenden Anfangswerten.",
            "taskDemandEn": "For a fresh independent graphical analysis, use a personal safe drop recording with repeats, a calibrated scale and known frame timing, or a separately supplied, clearly attributed recording/measurement series with documented calibration and time base. Choose upward positive and t = 0 during the fall; alternatively change the position origin and axis direction at release from rest. Determine g graphically and obtain a law with appropriate initial values.",
            "expectedPerformanceDe": "Kennzeichnet eigene oder fremde Messdaten samt Herkunft und zeigt eine eigenständige grafische Bestimmung von g passend zu den Anfangsbedingungen. Eine grafische quadratische Anpassung mit negativem quadratischem Koeffizienten und v0 < 0 bei aufwärts positiver Achse und Nullzeit während des Falls ist eine Möglichkeit; bei Freigabe aus Ruhe sind andere passende grafische Bestimmungen zulässig. Optionale Modellreferenz: Freigabe aus Ruhe bei y = 0,80 m, aufwärts positiv, Nullzeit bei y0 = 0,60 m und g = 9,8 m/s² ergibt v0 ≈ −1,98 m/s sowie y(0,10 s) ≈ 0,353 m. Berichtet die selbst erschlossenen Werte mit ihren Unsicherheiten und prüft das Gesetz am eigenständig erstellten Graphen; maßgeblich ist die Messverträglichkeit, nicht die Übereinstimmung mit den Referenzwerten.",
            "expectedPerformanceEn": "Identifies personal or supplied measurements and their provenance and independently determines g graphically in a way suited to the initial conditions. A graphical quadratic fit with a negative quadratic coefficient and v0 < 0 for upward positive and an in-flight time origin is one option; other appropriate graphical determinations are acceptable for release from rest. Optional model reference: release from rest at y = 0.80 m, upward positive, time origin at y0 = 0.60 m and g = 9.8 m/s² give v0 ≈ −1.98 m/s and y(0.10 s) ≈ 0.353 m. Reports independently inferred values with their uncertainties and checks the law against the independently constructed graph; agreement with the measurements within uncertainty, rather than with the reference values, is decisive.",
            "understandingFocusDe": "Koordinaten und Nullzeit ändern Koeffizienten und Anfangswerte, aber nicht den erschlossenen Betrag der Fallbeschleunigung.",
            "understandingFocusEn": "Coordinates and time origin change coefficients and initial values but not the inferred magnitude of gravitational acceleration."
          }
        ]
      }
    },
    {
      "goalId": "89a8cf15-7ba4-46c1-b1dc-fd161b20d9c2",
      "reason": "Dieselbe Zeit verbindet die unabhängigen horizontalen und vertikalen Bewegungen; ihre gemeinsame Ortsdarstellung ergibt die parabelförmige Flugbahn. / The same time connects independent horizontal and vertical motions; their joint position representation yields the parabolic trajectory.",
      "profile": {
        "archetype": "experiment",
        "expectations": [
          {
            "id": "record-horizontal-launch",
            "essentialUnderstandingDe": "Ein waagerechter Start bedeutet vy0 = 0; beide Ortskomponenten müssen zu denselben Zeitpunkten erfasst werden. Eine geneigte Freigabe oder perspektivisch verzerrte Aufnahme kann die Deutung verfälschen.",
            "essentialUnderstandingEn": "A horizontal launch means vy0 = 0; both position components must be recorded at the same times. An inclined release or perspective-distorted recording can bias interpretation.",
            "observablePerformanceDe": "Plant und führt selbst einen niedrigen waagerechten Wurf zur Untersuchung der Teilbewegungen aus. Kontrolliert Startausrichtung und Höhe, kalibriert Orts- und Zeitmessung und erhebt eigene zeitgleiche x-y-Daten. Dokumentiert Rohdaten, eigene Beiträge und Unsicherheiten; sichert Flugbereich und Auffangen.",
            "observablePerformanceEn": "Plans and personally performs a low horizontal launch to investigate component motions. Controls launch alignment and height, calibrates position and time measurement and collects personal simultaneous x-y data. Documents raw data, personal contributions and uncertainties; secures the flight area and catch."
          },
          {
            "id": "test-component-superposition",
